#include <iostream>
#include <iomanip>
#include <vector>
#include <cmath>
#include <Eigen/Dense>
#include <sstream>
#include <string>
#include <algorithm>

// Helper function to format double in scientific notation
std::string to_scientific(double x, int precision = 6) {
    std::ostringstream oss;
    oss << std::scientific << std::setprecision(precision) << x;
    return oss.str();
}

// Function to compute stiffness matrix for a triangular membrane element
// Input coords: [x1,y1,z1, x2,y2,z2, x3,y3,z3] (9 values) in *local* triangle frame (z=0)
void ktrmem(const std::vector<double>& coords, double E, double nu, double t,
            const std::vector<int>& nodes, Eigen::Matrix<double, 6, 6>& K_tri) {
    // coords: [x1,y1,z1, x2,y2,z2, x3,y3,z3] (9 values)
    // nodes: [n1,n2,n3] (3 node IDs, not used in computation here but for indexing)

    // Extract coordinates (we assume z=0, and triangle is in-plane)
    double x1 = coords[0], y1 = coords[1];
    double x2 = coords[3], y2 = coords[4];
    double x3 = coords[6], y3 = coords[7];

    // Compute area of triangle using cross product (2D)
    double v1x = x2 - x1, v1y = y2 - y1;
    double v2x = x3 - x1, v2y = y3 - y1;

    double area = 0.5 * std::abs(v1x * v2y - v1y * v2x);

    // Material matrix D for plane stress
    double denom = 1.0 - nu * nu;
    Eigen::Matrix<double, 3, 3> D;
    D << E/(denom), E*nu/(denom), 0.0,
         E*nu/(denom), E/(denom), 0.0,
         0.0, 0.0, E*(1.0-nu)/(2.0*denom);

    // Strain-displacement matrix B
    // For linear triangle: B = [b1 0 b2 0 b3 0; 0 c1 0 c2 0 c3; c1 b1 c2 b2 c3 b3] / (2*area)
    double b1 = y2 - y3;
    double b2 = y3 - y1;
    double b3 = y1 - y2;
    double c1 = x3 - x2;
    double c2 = x1 - x3;
    double c3 = x2 - x1;

    Eigen::Matrix<double, 3, 6> B;
    B.setZero();
    B(0,0) = b1; B(0,2) = b2; B(0,4) = b3;
    B(1,1) = c1; B(1,3) = c2; B(1,5) = c3;
    B(2,0) = c1; B(2,1) = b1; B(2,2) = c2; B(2,3) = b2; B(2,4) = c3; B(2,5) = b3;
    B /= (2.0 * area);

    // Element stiffness matrix: K = t * area * B^T * D * B
    Eigen::Matrix<double, 6, 6> K = t * area * B.transpose() * D * B;

    K_tri = K;
}

// Compute 2x2 rotation matrix R from global to local frame for a triangle
// Local x-axis = from node0 to node1
// Local y-axis = in-plane, CCW 90 deg from x-axis
Eigen::Matrix2d compute_triangle_rotation(
    const std::pair<double, double>& n0,
    const std::pair<double, double>& n1,
    const std::pair<double, double>& n2) {

    // x-axis: from n0 to n1
    double dx = n1.first - n0.first;
    double dy = n1.second - n0.second;
    double len = std::sqrt(dx*dx + dy*dy);
    if (len < 1e-12) {
        return Eigen::Matrix2d::Identity();
    }
    dx /= len;
    dy /= len;

    // y-axis: CCW perpendicular: (-dy, dx)
    double nx = -dy;
    double ny = dx;

    // R maps global vector to local: u_local = R * u_global
    // So R = [x_hat • e_x, x_hat • e_y; y_hat • e_x, y_hat • e_y]
    // = [dx, dy; nx, ny]
    Eigen::Matrix2d R;
    R << dx, dy,
         nx, ny;
    return R;
}

// Transform a 2D point from global to local frame (origin at n0)
std::pair<double, double> transform_to_local(
    const std::pair<double, double>& p,
    const std::pair<double, double>& n0,
    const Eigen::Matrix2d& R) {

    double gx = p.first - n0.first;
    double gy = p.second - n0.second;

    // u_local = R * [gx; gy]
    double ux = R(0,0)*gx + R(0,1)*gy;
    double uy = R(1,0)*gx + R(1,1)*gy;

    return {ux, uy};
}

// Main CQUAD4 stiffness computation
Eigen::Matrix<double, 8, 8> compute_cquad4_stiffness(
    const std::vector<std::pair<double, double>>& nodes,
    double E, double nu, double t) {

    // Nodes: (0,0), (2,0), (2,1.5), (0,1.5) -> 4 nodes, 2 DOF each = 8 DOF total
    // Map to 2D coordinates (z=0 for all)

    // Define the 4 triangles as per the Fortran mapping M
    std::vector<std::vector<int>> triangles = {
        {0, 1, 3}, // triangle 1: nodes 1,2,4 (0-indexed: 0,1,3)
        {1, 2, 0}, // triangle 2: nodes 2,3,1 (0-indexed: 1,2,0)
        {2, 3, 1}, // triangle 3: nodes 3,4,2 (0-indexed: 2,3,1)
        {3, 0, 2}  // triangle 4: nodes 4,1,3 (0-indexed: 3,0,2)
    };

    // For the test case, pivot = node 0 (index 0), so skip triangle with index = 2 (0-indexed)
    std::vector<int> used_triangles = {0, 1, 3};

    // Initialize 8x8 stiffness matrix
    Eigen::Matrix<double, 8, 8> K_total = Eigen::Matrix<double, 8, 8>::Zero();

    // Process each used triangle
    for (int tri_idx : used_triangles) {
        const auto& tri = triangles[tri_idx];

        // Get global coordinates of the three nodes
        std::pair<double, double> n0 = nodes[tri[0]];
        std::pair<double, double> n1 = nodes[tri[1]];
        std::pair<double, double> n2 = nodes[tri[2]];

        // Compute rotation matrix R: global -> local (for this triangle)
        Eigen::Matrix2d R = compute_triangle_rotation(n0, n1, n2);

        // Transform all three nodes to local frame (with origin at n0)
        auto l0 = transform_to_local(n0, n0, R); // (0,0)
        auto l1 = transform_to_local(n1, n0, R); // (len, 0) ideally
        auto l2 = transform_to_local(n2, n0, R);

        // Build local coordinates vector: [x0,y0,0, x1,y1,0, x2,y2,0]
        std::vector<double> tri_coords_local;
        tri_coords_local.push_back(l0.first);  tri_coords_local.push_back(l0.second); tri_coords_local.push_back(0.0);
        tri_coords_local.push_back(l1.first);  tri_coords_local.push_back(l1.second); tri_coords_local.push_back(0.0);
        tri_coords_local.push_back(l2.first);  tri_coords_local.push_back(l2.second); tri_coords_local.push_back(0.0);

        // Compute triangle stiffness in local frame (6x6)
        Eigen::Matrix<double, 6, 6> K_local;
        ktrmem(tri_coords_local, E, nu, t, tri, K_local);

        // Build 6x6 rotation matrix Q = blkdiag(R,R,R)
        Eigen::Matrix<double, 6, 6> Q = Eigen::Matrix<double, 6, 6>::Zero();
        for (int i = 0; i < 2; ++i) {
            for (int j = 0; j < 2; ++j) {
                Q(i, j) = R(i, j);
                Q(i+2, j+2) = R(i, j);
                Q(i+4, j+4) = R(i, j);
            }
        }

        // Transform to global frame: K_global_tri = Q^T * K_local * Q
        Eigen::Matrix<double, 6, 6> K_global_tri = Q.transpose() * K_local * Q;

        // Map 6x6 triangle stiffness to 8x8 global stiffness
        // Triangle DOFs: node0->(0,1), node1->(2,3), node2->(4,5) for triangle 0
        // But we need to map to global DOFs: node0->(0,1), node1->(2,3), node2->(4,5), node3->(6,7)
        // For triangle {0,1,3}: DOFs are [0,1, 2,3, 6,7]
        std::vector<int> dof_map;
        if (tri_idx == 0) { // {0,1,3}
            dof_map = {0,1, 2,3, 6,7};
        } else if (tri_idx == 1) { // {1,2,0}
            dof_map = {2,3, 4,5, 0,1};
        } else if (tri_idx == 3) { // {3,0,2}
            dof_map = {6,7, 0,1, 4,5};
        }

        // Add contribution to global matrix
        for (int i = 0; i < 6; i++) {
            for (int j = 0; j < 6; j++) {
                int gi = dof_map[i];
                int gj = dof_map[j];
                K_total(gi, gj) += K_global_tri(i, j);
            }
        }
    }

    return K_total;
}

