    std::vector<std::pair<double, double>> nodes = {
        {0.0, 0.0},   // node 1
        {2.0, 0.0},   // node 2
        {2.0, 1.5},   // node 3
        {0.0, 1.5}    // node 4
    };

    double E = 200e9;      // Pa
    double nu = 0.3;
